package com.cinemora.movieorder;

import android.content.Intent;
import android.os.Bundle;
import android.widget.TextView;
import android.widget.Toast;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.auth.FirebaseUser;

import java.util.ArrayList;

/**
 * Activity for confirming checkout before processing payment.
 * Shows cart items, pricing summary, and credits opt-in.
 * After successful checkout, shows success screen.
 */
public class CheckoutSummaryActivity extends AppCompatActivity {

    private FirebaseManager firebaseManager;
    private FirebaseAuth mAuth;
    private CartItemAdapter cartAdapter;

    private RecyclerView rvPurchasedItems;
    private TextView tvOrderNumValue;
    private TextView tvDateValue;
    private TextView tvSubtotalValue;
    private TextView tvDiscountValue;
    private TextView tvTotalValue;
    private TextView tvCreditsUsedValue;
    private TextView tvRemainingCreditsValue;

    private Cart currentCart;
    private boolean creditsOpted;
    private int userCredits;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_checkout_summary);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        firebaseManager = new FirebaseManager();
        mAuth = FirebaseAuth.getInstance();

        // Get intent extras
        creditsOpted = getIntent().getBooleanExtra("creditsOpted", false);

        initializeViews();
        loadCartData();
    }

    private void initializeViews() {
        rvPurchasedItems = findViewById(R.id.rvPurchasedItems);
        tvOrderNumValue = findViewById(R.id.OrderNumValue);
        tvDateValue = findViewById(R.id.DateValue);
        tvSubtotalValue = findViewById(R.id.SubtotalValue);
        tvDiscountValue = findViewById(R.id.DiscountValue);
        tvTotalValue = findViewById(R.id.TotalValue);
        tvCreditsUsedValue = findViewById(R.id.CreditsUsedValue);
        tvRemainingCreditsValue = findViewById(R.id.RemainingCreditsValue);

        // Setup RecyclerView
        rvPurchasedItems.setLayoutManager(new LinearLayoutManager(this));
        cartAdapter = new CartItemAdapter(this, new ArrayList<>(), null);
        rvPurchasedItems.setAdapter(cartAdapter);
    }

    private void loadCartData() {
        FirebaseUser currentUser = mAuth.getCurrentUser();
        if (currentUser == null) {
            Toast.makeText(this, "Please login first", Toast.LENGTH_SHORT).show();
            finish();
            return;
        }

        // Load user's cart
        firebaseManager.getUserCart(currentUser.getUid(), new FirebaseManager.OnCartLoadedListener() {
            @Override
            public void onLoaded(Cart cart) {
                currentCart = cart;
                if (cart == null || cart.isEmpty()) {
                    Toast.makeText(CheckoutSummaryActivity.this, "Your cart is empty", Toast.LENGTH_SHORT).show();
                    finish();
                    return;
                }

                // Load user's credits
                firebaseManager.getUserData(currentUser.getUid(), new FirebaseManager.OnUserDataLoadedListener() {
                    @Override
                    public void onLoaded(User user) {
                        if (user != null) {
                            userCredits = user.getEarnedCredit();
                            updateUI();
                        }
                    }

                    @Override
                    public void onError(String message) {
                        Toast.makeText(CheckoutSummaryActivity.this, "Error loading user data", Toast.LENGTH_SHORT).show();
                    }
                });
            }

            @Override
            public void onError(String message) {
                Toast.makeText(CheckoutSummaryActivity.this, "Error loading cart: " + message, Toast.LENGTH_SHORT).show();
                finish();
            }
        });
    }

    private void updateUI() {
        if (currentCart == null) return;

        // Update order info
        if (tvOrderNumValue != null) {
            tvOrderNumValue.setText("Preview");
        }
        if (tvDateValue != null) {
            tvDateValue.setText(DateUtils.formatOrderDate(DateUtils.getCurrentTimestamp()));
        }

        // Update cart items
        cartAdapter = new CartItemAdapter(this, currentCart.getItems(), null);
        rvPurchasedItems.setAdapter(cartAdapter);

        // Calculate and display pricing
        int subtotal = currentCart.getCartTotal();
        int discount = 0; // Default
        int totalCost = subtotal - discount;
        int creditsUsed = (creditsOpted && userCredits > 0) ? Math.min(userCredits, totalCost) : 0;
        int finalTotal = totalCost - creditsUsed;
        int remainingCredits = userCredits - creditsUsed;

        if (tvSubtotalValue != null) {
            tvSubtotalValue.setText(DateUtils.formatCurrency(subtotal));
        }
        if (tvDiscountValue != null) {
            tvDiscountValue.setText("- " + DateUtils.formatCurrency(discount));
        }
        if (tvTotalValue != null) {
            tvTotalValue.setText(DateUtils.formatCurrency(finalTotal));
        }
        if (tvCreditsUsedValue != null) {
            tvCreditsUsedValue.setText(DateUtils.formatCurrency(creditsUsed));
        }
        if (tvRemainingCreditsValue != null) {
            tvRemainingCreditsValue.setText(DateUtils.formatCurrency(remainingCredits));
        }
    }

    private void processCheckout() {
        if (currentCart == null || currentCart.isEmpty()) {
            Toast.makeText(this, "Cart is empty", Toast.LENGTH_SHORT).show();
            return;
        }

        FirebaseUser currentUser = mAuth.getCurrentUser();
        if (currentUser == null) {
            Toast.makeText(this, "Please login first", Toast.LENGTH_SHORT).show();
            return;
        }

        // First check for duplicate purchases
        boolean[] hasDuplicates = {false};
        for (CartItem item : currentCart.getItems()) {
            firebaseManager.checkUserOwnsMovie(currentUser.getUid(), item.getMovieId(), new FirebaseManager.OnPurchaseVerifyListener() {
                @Override
                public void onAlreadyOwned() {
                    Toast.makeText(CheckoutSummaryActivity.this, "You already own '" + item.getMovieName() + "'", Toast.LENGTH_SHORT).show();
                    hasDuplicates[0] = true;
                    // Don't proceed with checkout
                }

                @Override
                public void onNotOwned() {
                    // Continue with checkout
                    executeCheckout(currentUser.getUid());
                }

                @Override
                public void onError(String message) {
                    Toast.makeText(CheckoutSummaryActivity.this, "Error checking ownership: " + message, Toast.LENGTH_SHORT).show();
                }
            });
        }

        if (!hasDuplicates[0]) {
            executeCheckout(currentUser.getUid());
        }
    }

    private void executeCheckout(String userId) {
        firebaseManager.checkoutCart(userId, creditsOpted, new FirebaseManager.OnOrderDetailLoadedListener() {
            @Override
            public void onLoaded(Order order) {
                // Show success screen
                showSuccessScreen(order);
            }

            @Override
            public void onError(String message) {
                Toast.makeText(CheckoutSummaryActivity.this, "Checkout failed: " + message, Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void showSuccessScreen(Order order) {
        // The layout is already a success screen, just update the order number
        if (tvOrderNumValue != null && order != null) {
            tvOrderNumValue.setText("Order #" + order.getOrderId().substring(Math.max(0, order.getOrderId().length() - 5)));
        }

        // Setup success screen buttons
        Button btnViewMyMovies = findViewById(R.id.btnViewMyMovies);
        Button btnBackToHome = findViewById(R.id.btnBackToHome);

        if (btnViewMyMovies != null) {
            btnViewMyMovies.setOnClickListener(v -> {
                // Navigate to orders/library
                Intent intent = new Intent(this, MainActivity.class);
                intent.putExtra("navigateTo", "orders");
                startActivity(intent);
                finish();
            });
        }

        if (btnBackToHome != null) {
            btnBackToHome.setOnClickListener(v -> {
                Intent intent = new Intent(this, MainActivity.class);
                startActivity(intent);
                finish();
            });
        }
    }
}

package com.cinemora.movieorder;

import android.os.Bundle;
import android.widget.Toast;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.auth.FirebaseUser;

import java.util.ArrayList;
import java.util.List;

/**
 * Activity for showing order details after checkout.
 * Shows a list of orders using item_order.xml layout.
 */
public class CheckoutSummaryActivity extends AppCompatActivity {

    private FirebaseManager firebaseManager;
    private OrderAdapter orderAdapter;

    private RecyclerView rvPurchasedItems;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_checkout_summary);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        firebaseManager = new FirebaseManager();

        initializeViews();
        loadOrders();
    }

    private void initializeViews() {
        rvPurchasedItems = findViewById(R.id.rvPurchasedItems);

        // Setup RecyclerView
        rvPurchasedItems.setLayoutManager(new LinearLayoutManager(this));
        orderAdapter = new OrderAdapter(this, new ArrayList<>());
        rvPurchasedItems.setAdapter(orderAdapter);
    }

    private void loadOrders() {
        firebaseManager.getUserOrders(firebaseManager.getCurrentUserId(), new FirebaseManager.OnOrdersLoadedListener() {
            @Override
            public void onLoaded(List<Order> orders) {
                updateOrdersList(orders);
            }

            @Override
            public void onError(String message) {
                Toast.makeText(CheckoutSummaryActivity.this, "Error loading orders: " + message, Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void updateOrdersList(List<Order> orders) {
        orderAdapter = new OrderAdapter(this, orders);
        rvPurchasedItems.setAdapter(orderAdapter);
    }
}
